/**
 * Planning: turn a date range plus a density profile into an exact list of
 * commits to create.
 *
 * The planner is pure. It never touches git, the filesystem, or the clock, so
 * a plan can be rendered, asserted on in tests, and regenerated byte-for-byte
 * from the same inputs.
 */

import { eachDay, isWeekend, toKey } from "./calendar.js";
import { createRandom, randomInt } from "./random.js";

/**
 * Density profiles, tuned to read as natural activity rather than a solid
 * block of one colour.
 *
 * `weekday` / `weekend` are inclusive commit-count ranges; `rest` is the
 * chance that a day stays empty. Real contribution graphs have gaps, and the
 * gaps are what make the busy days look deliberate.
 */
export const PROFILES = {
  subtle: {
    summary: "Light, low-key presence. Mostly empty calendar with a few marks.",
    weekday: [0, 2],
    weekend: [1, 4],
    rest: 0.42,
  },
  balanced: {
    summary: "Steady weekday rhythm with visibly stronger weekends.",
    weekday: [1, 3],
    weekend: [4, 7],
    rest: 0.26,
  },
  premium: {
    summary: "Deep, consistent coverage. The profile default.",
    weekday: [1, 4],
    weekend: [4, 9],
    rest: 0.12,
  },
  dense: {
    summary: "Maximum saturation. Use sparingly — no contrast left.",
    weekday: [3, 7],
    weekend: [8, 14],
    rest: 0.05,
  },
};

export const DEFAULT_PROFILE = "premium";
export const DEFAULT_MAX_PER_DAY = 18;

/**
 * Build a commit plan.
 *
 * @param {object} options
 * @param {Date}   options.from          First day of the range (inclusive).
 * @param {Date}   options.to            Last day of the range (inclusive).
 * @param {string} options.profile       Key of PROFILES.
 * @param {string} options.seed          Any string; identical seeds match.
 * @param {Date}   options.today         Reference "now" — days after it are skipped.
 * @param {Map<string, number>} [options.history]  Existing commits per date key.
 * @param {boolean} [options.skipExisting]         Subtract existing commits per day.
 * @param {number}  [options.maxPerDay]            Hard ceiling per day.
 * @param {number}  [options.weekday]              Override profile weekday range.
 * @param {number}  [options.weekend]              Override profile weekend range.
 */
export function buildPlan({
  from,
  to,
  profile = DEFAULT_PROFILE,
  seed = "default",
  today,
  history = new Map(),
  skipExisting = false,
  maxPerDay = DEFAULT_MAX_PER_DAY,
  weekday,
  weekend,
}) {
  const preset = PROFILES[profile];

  if (!preset) {
    throw new Error(
      `unknown profile "${profile}" — choose one of: ${Object.keys(PROFILES).join(", ")}`,
    );
  }

  const ceiling = Math.max(0, Math.floor(maxPerDay));
  const next = createRandom(seed);
  const days = [];

  for (const date of eachDay(from, to)) {
    const key = toKey(date);
    const weekendDay = isWeekend(date);

    if (date > today) {
      days.push({ key, date, weekend: weekendDay, count: 0, state: "future" });
      continue;
    }

    const override = weekendDay ? weekend : weekday;
    let count;

    if (override !== undefined) {
      // An explicit count means exactly that: no rest days, no variation.
      count = Math.max(0, Math.floor(override));
    } else if (next() >= preset.rest) {
      const [min, max] = weekendDay ? preset.weekend : preset.weekday;
      count = randomInt(next, min, max);
    } else {
      count = 0;
    }

    if (skipExisting) {
      count = Math.max(0, count - (history.get(key) ?? 0));
    }

    count = Math.min(count, ceiling);

    days.push({
      key,
      date,
      weekend: weekendDay,
      count,
      state: count > 0 ? "planned" : "rest",
    });
  }

  const commits = [];
  let sequence = 0;

  for (const day of days) {
    if (day.count === 0) continue;

    for (let index = 0; index < day.count; index += 1) {
      sequence += 1;
      commits.push({
        key: day.key,
        sequence,
        index,
        timestamp: pickTimestamp(next, day.key, index),
      });
    }
  }

  const summary = {
    daysInRange: days.length,
    activeDays: days.filter((day) => day.count > 0).length,
    restDays: days.filter((day) => day.state === "rest").length,
    futureDays: days.filter((day) => day.state === "future").length,
    commits: commits.length,
    peak: days.reduce((max, day) => Math.max(max, day.count), 0),
  };

  return { profile, seed, days, commits, summary };
}

/**
 * Spread commits across a plausible working day so two commits on the same
 * date never share a timestamp.
 */
function pickTimestamp(next, key, index) {
  const base = new Date(`${key}T00:00:00.000Z`);
  const hour = randomInt(next, 9, 21);
  const minute = randomInt(next, 0, 59);
  const second = randomInt(next, 0, 59);

  base.setUTCHours(hour, minute, second, index);

  return base;
}
